(()=>{const toggle=document.getElementById('navToggle');addEventListener('director:menu',()=>{if(!document.getElementById('authOverlay').classList.contains('hidden'))return;const open=document.body.classList.toggle('menu-open');toggle.setAttribute('aria-expanded',String(open));document.getElementById('sidebarScrim').inert=!open;if(open)document.querySelector('.tab-btn.active')?.focus()});const back=document.createElement('a');back.href='index.html';back.className='minimal-public-link';back.textContent='← Torna al portfolio';document.querySelector('.auth-form-side').prepend(back);})();
